import copy, json, hashlib

ROOT=Path(__file__).resolve().parents[3]
BASE=Path(__file__).resolve().parent
PROJECT=BASE.parent
PROOF=ROOT/'production/batches/sakurai-planning-game-design/proof-avoid-game-comparisons'
def read(p): return json.loads(p.read_text(encoding='utf-8-sig'))
def save(p,d): p.write_text(json.dumps(d,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def sha(p): return hashlib.sha256(p.read_bytes()).hexdigest()
def rel(p): return p.relative_to(ROOT).as_posix()
now=datetime.now(timezone.utc).isoformat()
destination=BASE/'native-cue-proposal-v2.json'
assert not destination.exists(), 'Read the saved correction; do not repeat planning.'
