measured=read(BASE/'measured-paragraphs-expanded15.json')
measurements={s['id']:s for s in measured['scenes']}
def duration(c):
 fps=c['nativeFps'];c.update(inSeconds=c['startFrame']/fps,outSeconds=c['endFrameExclusive']/fps,seconds=(c['endFrameExclusive']-c['startFrame'])/fps)
def group(scene,p): return next(g for g in proposal['groups'] if g['sceneId']==scene and g['paragraph']==p)
excluded={'action-08','action-55','action-14','action-23','action-17','action-12','action-13'}
removed=[]
for g in proposal['groups']:
 removed.extend(c for c in g['sourceCuts'] if c['id'] in excluded)
 g['sourceCuts']=[c for c in g['sourceCuts'] if c['id'] not in excluded]
 for c in g['sourceCuts']:
  if c['id']=='action-35':c['endFrameExclusive']=827;c['newExactBoundaryPixelReview']=True
  if c['id']=='action-36':c['startFrame']=827;c['endFrameExclusive']=961;c['newExactBoundaryPixelReview']=True
  duration(c)
 # All measured current15 paragraphs are locked;14 uses the continuous special prefix.
 if g['sceneId']=='15':
  p=next(p for p in measurements['15']['paragraphs'] if p['paragraph']==g['paragraph'])
  g.update(audioFromSeconds=p['pcmFromSample']/24000,audioToSeconds=p['pcmToSample']/24000,voiceSeconds=p['pcmSeconds'])
# Mine combat must not appear beneath the Pepper device claim.
pepper=group('12',2);mine=group('12',3)
moved=[c for c in pepper['sourceCuts'] if c['sourceVideoId']=='CJ0_Xh59b98']
pepper['sourceCuts']=[c for c in pepper['sourceCuts'] if c not in moved]
for c in moved:c.update(sceneId='12',paragraph=3)
mine['sourceCuts'].extend(moved)
pepper.update(whiteExplanationTail=True,note='Pepper cannon/mech only. The unknown cost/win-condition tail is a white2.5D question. Mine combat moved to the following generic condition paragraph.')
group('15',3).update(whiteExplanationTail=True,note='Keep water/lava emergence and a visible boss shot; reject0.3/0.5-second flashes. Movement/target wording is a white comparison after the actual shots. Obtain a longer firing action if the observed shot is insufficient.')
group('04',1)['note']='Music-page walk stops before native827 gap cut. Gap starts827 and stops before native961 stair cut; earlier rounded14/16.5-second extension was rejected.'
for g in proposal['groups']:
 g['sourceSeconds']=sum(c['seconds'] for c in g['sourceCuts'])
 voice=g['voiceSeconds']
 g['minimumActionObservationExtraSeconds']=max(0,g['sourceSeconds']-voice)
 g['unresolvedVoiceCoverageSeconds']=0 if g['whiteExplanationTail'] else max(0,voice-g['sourceSeconds'])
 g['proposedExplanationSeconds']=max(0,voice-g['sourceSeconds']) if g['whiteExplanationTail'] else 0
cuts=[c for g in proposal['groups'] for c in g['sourceCuts']]
for sid in {c['sourceVideoId'] for c in cuts}:
 ordered=sorted([c for c in cuts if c['sourceVideoId']==sid],key=lambda c:c['startFrame'])
 for a,b in zip(ordered,ordered[1:]):assert a['endFrameExclusive']<=b['startFrame'],(sid,a['id'],b['id'])
originalWhite=sum(s['speechSeconds'] for s in measured['scenes'] if s['id'] in ['01','03','05','07','09','11'])
additionalWhite=sum(g['proposedExplanationSeconds'] for g in proposal['groups'])
additionalWhite+=measurements['13']['paragraphs'][-1]['pcmSeconds']
additionalWhite+=measurements['14']['speechSeconds']-group('14',1)['audioToSeconds']
actual=sum(c['seconds'] for c in cuts)
proposal.update(sourceUniqueSeconds=actual,sourceAllNonOverlapping=True,excludedMicroCuts=[{'id':c['id'],'sourceVideoId':c['sourceVideoId'],'seconds':c['seconds'],'reason':'Subsecond isolated flash is too brief for the claimed action; not used to fill actual quota.'} for c in removed],allCurrent15PcmPreserved=True,current15Index=rel(BASE/'narration-expanded15-index.json'),currentSpeechSeconds=sum(s['speechSeconds'] for s in measured['scenes']),proposedExplanationSeconds=originalWhite+additionalWhite,minimumRelatedAdditionalActualSeconds=max(0,1.5*(originalWhite+additionalWhite)-actual),bodyRatioApproved=False,exactNewNativeEdgesReviewed=False,allCaptionPixelsReviewed=False)
save(destination,proposal)
